-- Élevage : cinq nouveaux placements (chèvres, moutons, porcs, lapins, bovins) ajoutés au réglage `invest` s'il est déjà enregistré en base.
UPDATE game_setting SET value = jsonb_set(value, '{options}', (value->'options') || $j$[{"id": "elev_chevres", "kind": "FARM", "emoji": "🐐", "nameFr": "Élevage de chèvres (10 têtes)", "nameEn": "Goat herd (10 head)", "descFr": "Achat de chevrettes, soins vétérinaire et fourrage. Revente à la tabaski. 20 jours.", "descEn": "Kids, vet care and fodder. Sold at Tabaski. 20 days.", "cost": 90000, "gameDays": 20, "minReturnBp": 1500, "maxReturnBp": 6000, "failBp": 1200}, {"id": "elev_moutons", "kind": "FARM", "emoji": "🐑", "nameFr": "Embouche de moutons (8 bêtes)", "nameEn": "Sheep fattening (8 head)", "descFr": "Engraissement pour la fête de Tabaski. Risque de maladie. 25 jours.", "descEn": "Fattening for Tabaski. Disease risk. 25 days.", "cost": 160000, "gameDays": 25, "minReturnBp": 2500, "maxReturnBp": 9000, "failBp": 1500}, {"id": "elev_porcs", "kind": "FARM", "emoji": "🐖", "nameFr": "Porcherie (6 truies et porcelets)", "nameEn": "Pig farm (6 sows and piglets)", "descFr": "Vente de porcs au marché. Attention à la peste porcine. 30 jours.", "descEn": "Pigs sold at market. Beware of swine fever. 30 days.", "cost": 220000, "gameDays": 30, "minReturnBp": 3000, "maxReturnBp": 10000, "failBp": 2000}, {"id": "elev_lapins", "kind": "FARM", "emoji": "🐇", "nameFr": "Clapier de lapins (50 lapins)", "nameEn": "Rabbit hutch (50 rabbits)", "descFr": "Petit élevage rapide, viande vendue aux restaurants. 15 jours.", "descEn": "Quick small farm, meat sold to restaurants. 15 days.", "cost": 70000, "gameDays": 15, "minReturnBp": 1000, "maxReturnBp": 4500, "failBp": 1000}, {"id": "elev_bovins", "kind": "FARM", "emoji": "🐂", "nameFr": "Embouche de bovins (5 bœufs, Savanes)", "nameEn": "Cattle fattening (5 oxen, Savanes)", "descFr": "Gros investissement, forte valeur à la revente. 45 jours.", "descEn": "Large investment, high resale value. 45 days.", "cost": 600000, "gameDays": 45, "minReturnBp": 3500, "maxReturnBp": 12000, "failBp": 1800}]$j$::jsonb)
WHERE key = 'invest' AND NOT (value->'options') @> '[{"id": "elev_chevres"}]'::jsonb;
